def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    marker_cols=[c for c in range(w) if grid[h-1][c]==5]
    for c in marker_cols:
        # Each marker column is completed by extending the nearest object's
        # color to both ends; ties break toward the upper object.
        seeds=[r for r in range(h) if grid[r][c]!=0]
        for r in range(h):
            if grid[r][c]==0 and seeds:
                seed=min(seeds,key=lambda s:(abs(s-r),s))
                out[r][c]=grid[seed][c]
    return out

